    { "Mass spectrometry-based secretome analysis was performed using the Q-Exactive Plus mass spectrometer.": "Q-Exactive Plus mass spectrometer" },
    { "Mouse anti-human monoclonal antibodies were used to neutralize CXCL8/IL-8, Serpin E1/PAI-1, PDGF-AA, and MIF.": "CXCL8/IL-8" },
    { "Using the public TCGA provisional dataset (cBioPortal), we studied patient outcome in a lung adenocarcinoma cohort.": "lung adenocarcinoma cohort" }
